mapper.select:
SELECT m.*,
       (SELECT COUNT(*) FROM requirement_modules rm WHERE rm.module_id = m.id) AS requirement_count
FROM project_modules m WHERE m.id = #{id}

SELECT m.* FROM project_modules m
WHERE m.category = #{category}
  AND m.name = #{name}

      AND m.parent_id = #{parentId}
      AND m.parent_id IS NULL

  AND m.id <> #{excludeId}
LIMIT 1
